  credential_rotation_days Int? @db.Integer

  /// Timestamp of last credential rotation.
  last_credential_rotation DateTime? @db.Timestamptz

  /// Timestamp when API configuration was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when API configuration was last updated.
