  @@index([ecommerce_mall_customer_session_id])
  @@index([ecommerce_mall_product_id])
  @@index([ecommerce_mall_order_id])
  @@index([status])
  @@index([overall_rating])
  @@index([created_at])
  @@index([helpful_count])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

